import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"یکجا اختصاص مخالف قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/47-反垄断法.md","filePath":"ur/47-反垄断法.md","lastUpdated":null}'),d={name:"ur/47-反垄断法.md"};function e(o,t,h,n,s,b){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="یکجا-اختصاص-مخالف-قانون" tabindex="-1">یکجا اختصاص مخالف قانون <a class="header-anchor" href="#یکجا-اختصاص-مخالف-قانون" aria-label="Permalink to &quot;یکجا اختصاص مخالف قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>47</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>یکجا اختصاص مخالف، لوٹ مار مخالف، مارکیٹ مقابلہ، وسائل کی یکجا اختصاص، سادھنہ کی یکجا اختصاص</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《یکجا اختصاص مخالف قانون》 اینکر سمبیوسس تہذیب کے پانچ معاون قوانین میں سے ایک ہے، اور اس کا مقصد یکجا اختصاص کے رویوں کی روک تھام اور روکنا، مارکیٹ کے منصفانہ مقابلے کی حفاظت، معاشی کارکردگی کو بڑھانا، صارفین کے مفادات اور سماجی عوامی مفادات کی حفاظت، اور سمبیوسس معیشت کے صحت مند ترقی کو فروغ دینا ہے۔ اینکر سمبیوسس تہذیب میں، یکجا اختصاص مخالف صرف روایتی معاشی شعبے کی یکجا اختصاص کے خلاف نہیں ہے، بلکہ سادھنہ وسائل کی یکجا اختصاص، علم کی یکجا اختصاص اور位面 کی یکجا اختصاص جیسی خصوصی شکلوں کے خلاف بھی ہے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>منصفانہ مقابلے کا اصول</td><td>منصفانہ مقابلے کی مارکیٹ کی ترتیب کی حفاظت، مقابلے کو خارج کرنے یا محدود کرنے والے یکجا اختصاص کے رویوں کی ممانعت</td></tr><tr><td>لوٹ مار مخالف کا اصول</td><td>یکجا اختصاص مخالف کا بنیادی نقطہ لوٹ مار مخالف ہے، اور یکجا اختصاص کرنے والوں کو ان کی یکجا اختصاص کی پوزیشن کے ذریعے تمام زندگیوں کے مفادات لوٹنے سے روکنا</td></tr><tr><td>وسائل کھلنے کا اصول</td><td>عوامی سادھنہ وسائل اور بنیادی علم کو ضرور پوری معاشرے کے لیے کھلا رکھنا چاہیے، اور نجی یکجا اختصاص ممنوع ہے</td></tr><tr><td>کارکردگی اور انصاف کے توازن کا اصول</td><td>یکجا اختصاص مخالف کو ضرور مقابلے کی کارکردگی کی حفاظت کرنی چاہیے، ساتھ ہی ضرورت سے زیادہ منتشر ہونے کی وجہ سے وسائل کے ضیاع کی روک تھام کرنی چاہیے</td></tr><tr><td>بین位面 قابل اطلاق اصول</td><td>یکجا اختصاص مخالف قانون ہینگیوانژو کے اندر تمام位面 اور مارکیٹوں پر لاگو ہوتا ہے، اور بین位面 یکجا اختصاص بھی ضابطے کے تابع ہے</td></tr></tbody></table><h2 id="ثانياً-یکجا-اختصاص-کے-رویوں-کی-اقسام" tabindex="-1">ثانياً. یکجا اختصاص کے رویوں کی اقسام <a class="header-anchor" href="#ثانياً-یکجا-اختصاص-کے-رویوں-کی-اقسام" aria-label="Permalink to &quot;ثانياً. یکجا اختصاص کے رویوں کی اقسام&quot;">​</a></h2><p>اس قانون کے ذریعے ضابطے کے تابع یکجا اختصاص کے رویوں میں درج ذیل چار اقسام شامل ہیں:</p><h3 id="_1-یکجا-اختصاص-کے-معاہدے" tabindex="-1">(1) یکجا اختصاص کے معاہدے <a class="header-anchor" href="#_1-یکجا-اختصاص-کے-معاہدے" aria-label="Permalink to &quot;(1) یکجا اختصاص کے معاہدے&quot;">​</a></h3><p>یکجا اختصاص کے معاہدے سے مراد مقابلے کو خارج کرنے، محدود کرنے والے معاہدے، فیصلے یا دیگر باہمی رویے ہیں، اور ان میں شامل ہیں:</p><ol><li><strong>افقی یکجا اختصاص کے معاہدے</strong>: مقابلے کے تعلق رکھنے والے کاروباریوں کے درمیان قیمت مقرر کرنا، پیداوار محدود کرنا، مارکیٹ تقسیم کرنا، مشترکہ طور پر لین دین سے انکار کرنا وغیرہ کے معاہدے۔</li><li><strong>عمودی یکجا اختصاص کے معاہدے</strong>: کاروباری اور لین دین کے فریق کے درمیان دوبارہ فروخت کی قیمت مقرر کرنا، کم از کم دوبارہ فروخت کی قیمت محدود کرنا وغیرہ کے معاہدے۔</li><li><strong>سادھنہ وسائل کی یکجا اختصاص کے معاہدے</strong>: سادھنہ فرقوں کے درمیان سادھنہ وسائل کے علاقے تقسیم کرنا، وسائل کی قیمت یکجا کرنا، وسائل کی فراہمی محدود کرنا وغیرہ کے معاہدے۔</li><li><strong>علم کی یکجا اختصاص کے معاہدے</strong>: تعلیمی اداروں اور سادھنہ فرقوں کے درمیان سادھنہ کے طریقے بند کرنا، علم کی تبلیغ محدود کرنا، ٹیوشن فیس کے معیار یکجا کرنا وغیرہ کے معاہدے۔</li></ol><h3 id="_2-مارکیٹ-کے-غالب-مقام-کا-غلط-استعمال" tabindex="-1">(2) مارکیٹ کے غالب مقام کا غلط استعمال <a class="header-anchor" href="#_2-مارکیٹ-کے-غالب-مقام-کا-غلط-استعمال" aria-label="Permalink to &quot;(2) مارکیٹ کے غالب مقام کا غلط استعمال&quot;">​</a></h3><p>مارکیٹ کے غالب مقام سے مراد وہ مارکیٹ کی پوزیشن ہے جس میں کاروباری متعلقہ مارکیٹ میں سامان کی قیمت، مقدار یا دیگر لین دین کی شرائط کو کنٹرول کرنے کی صلاحیت رکھتا ہے، یا دوسرے کاروباریوں کو متعلقہ مارکیٹ میں داخل ہونے میں رکاوٹ ڈالنے یا اثر انداز کرنے کی صلاحیت رکھتا ہے۔ مارکیٹ کے غالب مقام کے غلط استعمال کے رویوں میں شامل ہیں:</p><table tabindex="0"><thead><tr><th>رویے کی قسم</th><th>مخصوص اظہار</th></tr></thead><tbody><tr><td>غیر منصفانہ قیمت مقرر کرنا</td><td>غیر منصفانہ زیادہ قیمت پر سامان بیچنا یا غیر منصفانہ کم قیمت پر سامان خریدنا</td></tr><tr><td>لوٹ مار کی قیمت مقرر کرنا</td><td>جائز وجہ کے بغیر، لاگت سے کم قیمت پر سامان بیچنا، حریفوں کو ختم کرنا</td></tr><tr><td>لین دین سے انکار</td><td>جائز وجہ کے بغیر، لین دین کے فریق کے ساتھ لین دین کرنے سے انکار</td></tr><tr><td>لین دین محدود کرنا</td><td>جائز وجہ کے بغیر، لین دین کے فریق کو صرف اپنے ساتھ لین دین کرنے پر مجبور کرنا</td></tr><tr><td>منسلک فروخت</td><td>جائز وجہ کے بغیر سامان منسلک فروخت کرنا، یا لین دین کے وقت دیگر غیر منصفانہ شرائط عائد کرنا</td></tr><tr><td>امتیازی سلوک</td><td>جائز وجہ کے بغیر، ایک جیسی شرائط والے لین دین کے فریقوں کے ساتھ لین دین کی قیمت وغیرہ شرائط میں امتیازی سلوک کرنا</td></tr><tr><td>سادھنہ وسائل کی بندش</td><td>سادھنہ وسائل کی یکجا اختصاص کی پوزیشن کا استعمال کرتے ہوئے، حریفوں یا صارفین کو ضروری وسائل فراہم کرنے سے انکار</td></tr><tr><td>علم کی بندش</td><td>علم کی یکجا اختصاص کی پوزیشن کا استعمال کرتے ہوئے، بنیادی سادھنہ کے طریقے بند کرنا، اور طلباء کو زیادہ فیس ادا کرنے پر مجبور کرنا</td></tr></tbody></table><h3 id="_3-کاروباریوں-کا-مرتکز-ہونا" tabindex="-1">(3) کاروباریوں کا مرتکز ہونا <a class="header-anchor" href="#_3-کاروباریوں-کا-مرتکز-ہونا" aria-label="Permalink to &quot;(3) کاروباریوں کا مرتکز ہونا&quot;">​</a></h3><p>کاروباریوں کا مرتکز ہونا سے مراد درج ذیل حالات ہیں: کاروباریوں کا انضمام؛ کاروباری حصص یا اثاثے حاصل کرنے کے ذریعے دوسرے کاروباریوں پر کنٹرول کی صلاحیت حاصل کرنا؛ کاروباری معاہدوں وغیرہ کے ذریعے دوسرے کاروباریوں پر کنٹرول کی صلاحیت حاصل کرنا یا دوسرے کاروباریوں پر فیصلہ کن اثر انداز کرنے کی صلاحیت رکھنا۔</p><p>اعلان کے معیار کو پورا کرنے والا کاروباریوں کا مرتکز ہونا، پہلے یکجا اختصاص مخالف نافذ ادارے کو اعلان کرنا چاہیے، اور اعلان نہ کرنے والا مرتکز ہونا نافذ نہیں کیا جا سکتا۔ یکجا اختصاص مخالف نافذ ادارے کاروباریوں کے مرتکز ہونے کا جائزہ لیتے وقت، درج ذیل عوامل پر غور کرنا چاہیے:</p><ol><li>مرتکز ہونے میں شریک کاروباریوں کی متعلقہ مارکیٹ میں مارکیٹ کا حصہ اور مارکیٹ پر ان کی کنٹرول کی طاقت۔</li><li>متعلقہ مارکیٹ کی مارکیٹ کی مرتکزیت۔</li><li>کاروباریوں کے مرتکز ہونے کا مارکیٹ میں داخلے اور تکنیکی ترقی پر اثر۔</li><li>کاروباریوں کے مرتکز ہونے کا صارفین اور دیگر متعلقہ کاروباریوں پر اثر۔</li><li>کاروباریوں کے مرتکز ہونے کا سادھنہ وسائل کی کھلنے اور علم کی تبلیغ پر اثر۔</li><li>کاروباریوں کے مرتکز ہونے کا قومی معاشی ترقی اور تمام نسلوں کی مشترکہ ترقی پر اثر۔</li></ol><h3 id="_4-انتظامی-اختیارات-کا-غلط-استعمال-کرکے-مقابلے-کو-خارج-کرنا،-محدود-کرنا" tabindex="-1">(4) انتظامی اختیارات کا غلط استعمال کرکے مقابلے کو خارج کرنا، محدود کرنا <a class="header-anchor" href="#_4-انتظامی-اختیارات-کا-غلط-استعمال-کرکے-مقابلے-کو-خارج-کرنا،-محدود-کرنا" aria-label="Permalink to &quot;(4) انتظامی اختیارات کا غلط استعمال کرکے مقابلے کو خارج کرنا، محدود کرنا&quot;">​</a></h3><p>انتظامی ادارے اور قانون، ضوابط کے ذریعے عوامی معاملات کے انتظام کے کام کرنے کی اجازت والی تنظیمیں انتظامی اختیارات کا غلط استعمال کرکے درج ذیل رویے نافذ نہیں کر سکتیں:</p><ol><li>یونٹ یا فرد کو ان کے مقرر کردہ کاروباریوں کے ذریعے فراہم کردہ سامان چلانے، خریدنے، استعمال کرنے پر محدود یا بالواسطہ محدود کرنا۔</li><li>علاقوں کے درمیان،位面 کے درمیان سامان کی آزادانہ گردش میں رکاوٹ ڈالنا۔</li><li>دوسرے علاقوں کے کاروباریوں، دوسرے位面 کے کاروباریوں کو مقامی ٹینڈر اور بولی میں حصہ لینے سے خارج کرنا یا محدود کرنا۔</li><li>دوسرے علاقوں کے کاروباریوں، دوسرے位面 کے کاروباریوں کو مقامی سرمایہ کاری یا شاخ قائم کرنے سے خارج کرنا یا محدود کرنا۔</li><li>کاروباریوں کو اس قانون میں طے شدہ یکجا اختصاص کے رویوں پر مجبور کرنا۔</li><li>مقابلے کو خارج کرنے، محدود کرنے والے مواد والے ضوابط تیار کرنا۔</li></ol><h2 id="ثالثاً-سادھنہ-کے-شعبے-میں-خصوصی-یکجا-اختصاص-مخالف-قواعد" tabindex="-1">ثالثاً. سادھنہ کے شعبے میں خصوصی یکجا اختصاص مخالف قواعد <a class="header-anchor" href="#ثالثاً-سادھنہ-کے-شعبے-میں-خصوصی-یکجا-اختصاص-مخالف-قواعد" aria-label="Permalink to &quot;ثالثاً. سادھنہ کے شعبے میں خصوصی یکجا اختصاص مخالف قواعد&quot;">​</a></h2><p>سادھنہ کا شعبہ اینکر سمبیوسس تہذیب میں یکجا اختصاص مخالف کا اہم شعبہ ہے، اور یہ قانون خصوصی قواعد قائم کرتا ہے:</p><ol><li><strong>بنیادی طریقے کھولنے کی واجب الادائیگی</strong>: تین سو اصل سادھنہ نظام کے بنیادی طریقے عوامی علم کے تحت آتے ہیں، اور کوئی تنظیم اور فرد انہیں یکجا اختصاص، بند یا فیس کے ساتھ نہیں سکھا سکتا۔</li><li><strong>سادھنہ وسائل کی منصفانہ تقسیم</strong>: عوامی سادھنہ وسائل مشترکہ پیداوار معاہدے کے نظام کے ذریعے منصفانہ طور پر تقسیم کیے جاتے ہیں، اور فرقوں یا افراد کے اعلیٰ معیار کے سادھنہ وسائل کی یکجا اختصاص ممنوع ہے۔</li><li><strong>سادھنہ میں امتیازی سلوک کی ممانعت</strong>: سادھنہ فرقے داخلے اور سکھانے میں نسل، اصل، سادھنہ کی سطح وغیرہ کی بنیاد پر امتیازی شرائط نہیں بنا سکتے۔</li><li><strong>اعلیٰ سطحی علم بانٹنے کی واجب الادائیگی</strong>:位面 کے اعلیٰ ترین طاقتور شخص کے معیار کو پورا کرنے والے سادھک کو، معقول دانشورانہ املاک کی حفاظت کی شرط پر، معاشرے کے ساتھ اپنے سادھنہ کے تجربات اور تحقیقی نتائج بانٹنے کی واجب الادائیگی ہے۔</li><li><strong>位面 ترقی کی یکجا اختصاص مخالف</strong>: نئے位面 کی ترقی کا حق کھلے مقابلے کے ذریعے تقسیم کیا جاتا ہے، اور چند طاقتوں کے位面 ترقی کے حق کی یکجا اختصاص ممنوع ہے۔</li></ol><h2 id="رابعاً-یکجا-اختصاص-مخالف-نافذ-ادارہ" tabindex="-1">رابعاً. یکجا اختصاص مخالف نافذ ادارہ <a class="header-anchor" href="#رابعاً-یکجا-اختصاص-مخالف-نافذ-ادارہ" aria-label="Permalink to &quot;رابعاً. یکجا اختصاص مخالف نافذ ادارہ&quot;">​</a></h2><p>ریاست یکجا اختصاص مخالف نافذ ادارہ قائم کرتی ہے، جو یکجا اختصاص مخالف نافذ کام کے لیے ذمہ دار ہے، اور درج ذیل فرائض سرانجام دیتی ہے:</p><ol><li>مقابلے کی پالیسی سے متعلق تحقیق اور مسودہ تیار کرنا۔</li><li>مارکیٹ کے مجموعی مقابلے کی صورتحال کی تحقیقات اور تشخیص کا انتظام کرنا، اور تشخیصی رپورٹ شائع کرنا۔</li><li>یکجا اختصاص مخالف رہنمائی تیار کرنا اور شائع کرنا۔</li><li>یکجا اختصاص مخالف انتظامی نافذ کام کو مربوط کرنا۔</li><li>یکجا اختصاص کے معاہدے، مارکیٹ کے غالب مقام کا غلط استعمال، غیر قانونی طور پر کاروباریوں کا مرتکز ہونا وغیرہ کے مقدمات کی تحقیقات اور سزا۔</li><li>انتظامی اختیارات کا غلط استعمال کرکے مقابلے کو خارج کرنے، محدود کرنے والے رویوں کی تحقیقات اور سزا۔</li></ol><p>یکجا اختصاص مخالف نافذ ادارہ قانون کے مطابق آزادانہ طور پر اپنے اختیارات استعمال کرتا ہے، اور انتظامی اداروں، سماجی تنظیموں اور افراد کی مداخلت سے آزاد ہے۔</p><h2 id="خامساً-قانونی-ذمہ-داری" tabindex="-1">خامساً. قانونی ذمہ داری <a class="header-anchor" href="#خامساً-قانونی-ذمہ-داری" aria-label="Permalink to &quot;خامساً. قانونی ذمہ داری&quot;">​</a></h2><p>اس قانون کی دفعات کی خلاف ورزی کرنے والے کارروائیاں جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائیں گی:</p><ul><li>یکجا اختصاص کے معاہدے طے کرنے اور نافذ کرنے پر، غیر قانونی رویے بند کرنے کا حکم، غیر قانونی آمدنی ضبط، اور پچھلے سال کی فروخت کی آمدنی کے ایک فیصد سے دس فیصد تک جرمانہ۔</li><li>مارکیٹ کے غالب مقام کا غلط استعمال کرنے پر، غیر قانونی رویے بند کرنے کا حکم، غیر قانونی آمدنی ضبط، اور پچھلے سال کی فروخت کی آمدنی کے ایک فیصد سے دس فیصد تک جرمانہ۔</li><li>غیر قانونی طور پر کاروباریوں کا مرتکز ہونا نافذ کرنے پر، مرتکز ہونا بند کرنے کا حکم، مقررہ وقت میں حصص یا اثاثے بیچنا، مقررہ وقت میں کاروبار منتقل کرنا، اور پچاس ہزار یوآن سے کم جرمانہ۔</li><li>انتظامی اختیارات کا غلط استعمال کرکے مقابلے کو خارج کرنے، محدود کرنے پر، اعلیٰ ادارہ کے ذریعے اصلاح کا حکم، اور براہ راست ذمہ دار افسران اور دیگر براہ راست ذمہ دار افراد کو قانون کے مطابق سزا دی جائے گی۔</li><li>یکجا اختصاص کے رویے دوسروں کو نقصان پہنچانے پر، قانون کے مطابق دیوانی معاوضے کی ذمہ داری اٹھائے گا۔</li><li>سنگین صورت حال جو جرم تشکیل دے، قانون کے مطابق فوجداری ذمہ داری عائد کی جائے گی۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《یکجا اختصاص مخالف قانون》 اینکر سمبیوسس تہذیب کے لوٹ مار مخالف نظریے کا معاشی اور سادھنہ کے شعبے میں قانونی ہتھیار ہے۔ یہ یکجا اختصاص کے معاہدے، مارکیٹ کے غالب مقام کا غلط استعمال، کاروباریوں کا مرتکز ہونا اور انتظامی یکجا اختصاص کو ضابطے میں لانے کے ذریعے، خاص طور پر سادھنہ وسائل کی یکجا اختصاص اور علم کی یکجا اختصاص کے لیے خصوصی قواعد قائم کرنے کے ذریعے، مارکیٹ مقابلے اور سادھنہ وسائل کی منصفانہ کھلنے کو یقینی بناتا ہے، اور یکجا اختصاص کو تمام زندگیوں کو لوٹنے کی نئی شکل بننے سے روکتا ہے، اور تمام نسلوں کی مشترکہ ترقی کے لیے منصفانہ مقابلے کا ادارہ جاتی ماحول محفوظ رکھتا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>42-消费者保护法 (صارفین کے تحفظ کا قانون)</li><li>18-修炼资源开放机制 (سادھنہ وسائل کھولنے کا نظام)</li><li>04-反掠夺主义核心论纲 (لوٹ مار مخالف نظریے کا بنیادی پروگرام)</li></ul>',35)])])}const u=a(d,[["render",e]]);export{c as __pageData,u as default};
